memberdef.definition:
using llvm::VPlanPatternMatch::AllUnaryRecipe_match = 
    UnaryRecipe_match<Op0_t, Opcode, VPWidenRecipe, VPReplicateRecipe,
                      VPWidenCastRecipe, VPInstruction>

using llvm::VPlanPatternMatch::BinaryVPInstruction_match = 
    BinaryRecipe_match<Op0_t, Op1_t, Opcode,  false,
                       VPInstruction>

using llvm::VPlanPatternMatch::AllBinaryRecipe_match = 
    BinaryRecipe_match<Op0_t, Op1_t, Opcode, Commutative, VPWidenRecipe,
                       VPReplicateRecipe, VPWidenCastRecipe, VPInstruction>

using llvm::VPlanPatternMatch::AllTernaryRecipe_match = 
    Recipe_match<std::tuple<Op0_t, Op1_t, Op2_t>, Opcode, false,
                 VPReplicateRecipe, VPInstruction, VPWidenSelectRecipe>
